<?php
namespace App\Services;
use App\Models\{BookingCuci,JenisServis,KendaraanPelanggan,PaketCuci,Pelanggan,Transaksi};
use Illuminate\Support\Facades\DB;
use RuntimeException;
class BookingCuciService {
 private function code():string{$code='BCW-'.now()->format('Ym').'-'.strtoupper(bin2hex(random_bytes(4)));while(BookingCuci::where('kode_booking',$code)->exists())$code='BCW-'.now()->format('Ym').'-'.strtoupper(bin2hex(random_bytes(4)));return $code;}
 public function actorPetugasId(?int $userId):?int{return DB::table('petugas')->where('id_user',$userId)->value('id_petugas') ?: DB::table('petugas')->where('status','aktif')->value('id_petugas');}
 public function create(int $customerId,int $vehicleId,int $packageId,string $date,string $time,?string $note):BookingCuci{return DB::transaction(function()use($customerId,$vehicleId,$packageId,$date,$time,$note){$customer=Pelanggan::findOrFail($customerId);$vehicle=$customer->kendaraan()->where('status','aktif')->findOrFail($vehicleId);$package=PaketCuci::where('status','aktif')->findOrFail($packageId);if(strtotime($date.' '.$time)<=time())throw new RuntimeException('Tanggal dan jam harus di masa depan.');$b=new BookingCuci();$b->forceFill(['kode_booking'=>$this->code(),'id_pelanggan'=>$customer->id_pelanggan,'id_kendaraan_pelanggan'=>$vehicle->id_kendaraan_pelanggan,'id_paket'=>$package->id_paket,'tanggal'=>$date,'jam'=>$time,'harga'=>$package->harga,'status'=>'menunggu','catatan'=>$note]);$b->save();return $b;});}
 public function confirm(int $id,int $petugasId):void{$this->transition($id,'diterima',$petugasId);}
 public function start(int $id,int $petugasId):void{$this->transition($id,'proses',$petugasId);}
 public function finalize(int $id,int $petugasId):Transaksi{return DB::transaction(function()use($id,$petugasId){$b=BookingCuci::lockForUpdate()->findOrFail($id);if($b->status!=='proses'||$b->id_transaksi!==null)throw new RuntimeException('Booking cuci belum siap difinalisasi atau sudah memiliki tagihan.');$code=$this->transactionCode();$tx=new Transaksi();$tx->forceFill(['kode_transaksi'=>$code,'id_pelanggan'=>$b->id_pelanggan,'id_petugas'=>$petugasId,'jenis_transaksi'=>'cuci_mobil','tanggal'=>now(),'subtotal'=>$b->harga,'diskon'=>0,'total'=>$b->harga,'status'=>'belum_bayar','catatan'=>'Tagihan '.$b->kode_booking])->save();$b->forceFill(['id_transaksi'=>$tx->id_transaksi,'id_petugas'=>$petugasId])->save();return $tx;});}
 private function transactionCode():string{do{$code='TRX-'.now()->format('Ym').'-'.strtoupper(bin2hex(random_bytes(4)));}while(Transaksi::where('kode_transaksi',$code)->exists());return $code;}
 public function cancel(int $id,int $customerId):void{DB::transaction(function()use($id,$customerId){$b=BookingCuci::whereKey($id)->where('id_pelanggan',$customerId)->lockForUpdate()->first();if(!$b||!in_array($b->status,['menunggu','diterima'],true))throw new RuntimeException('Booking cuci tidak dapat dibatalkan.');$b->forceFill(['status'=>'dibatalkan'])->save();});}
 private function transition(int $id,string $target,int $petugasId):void{DB::transaction(function()use($id,$target,$petugasId){$b=BookingCuci::lockForUpdate()->findOrFail($id);$allowed=['menunggu'=>['diterima'],'diterima'=>['proses'],'proses'=>[],'selesai'=>[],'dibatalkan'=>[]];if(!in_array($target,$allowed[$b->status]??[],true))throw new RuntimeException('Perubahan status car wash tidak diizinkan.');$b->forceFill(['status'=>$target,'id_petugas'=>$petugasId])->save();});}
 public function finalizeWithPromo(int $id,int $petugasId,?int $promoId=null):Transaksi{$tx=$this->finalize($id,$petugasId);if($promoId!==null)app(PromoEngineService::class)->applyToTransaction($tx,$promoId,'cuci_mobil');return$tx->fresh();}
}
